const [page, setPage] = useState(1);
const items = Array.from({ length: page * 5 }, (_, i) => `Documento ${i + 1}`);

<>
  <ul>
    {items.map((item) => (
      <li key={item}>{item}</li>
    ))}
  </ul>
  <Pagination type="more" totalPages={8} page={page} onPageChange={(next) => setPage(next)} />
</>

const [current, setCurrent] = useState(2);

<PaginationPage
  number={3}
  selected={current === 3}
  aria-label="Página 3"
  onClick={() => setCurrent(3)}
/>
